  public static class CustomTypeAdapterFactory implements TypeAdapterFactory {
    @SuppressWarnings("unchecked")
    @Override
    public <T> TypeAdapter<T> create(Gson gson, TypeToken<T> type) {
       if (!InterfaceDefinition.class.isAssignableFrom(type.getRawType())) {
         return null; // this class only serializes 'InterfaceDefinition' and its subtypes
       }
       final TypeAdapter<JsonElement> elementAdapter = gson.getAdapter(JsonElement.class);
       final TypeAdapter<InterfaceDefinition> thisAdapter
                        = gson.getDelegateAdapter(this, TypeToken.get(InterfaceDefinition.class));

       return (TypeAdapter<T>) new TypeAdapter<InterfaceDefinition>() {
           @Override
           public void write(JsonWriter out, InterfaceDefinition value) throws IOException {
             JsonObject obj = thisAdapter.toJsonTree(value).getAsJsonObject();
             elementAdapter.write(out, obj);
           }

           @Override
           public InterfaceDefinition read(JsonReader in) throws IOException {
             JsonElement jsonElement = elementAdapter.read(in);
             validateJsonElement(jsonElement);
             return thisAdapter.fromJsonTree(jsonElement);
           }

       }.nullSafe();
    }
  }

